contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        require(true);
        uint256 mySharesBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(amount <= mySharesBefore);

        bool ok = c.transfer(address(this), amount); if (__ESBMC_reverted()) return;

        assert(ok && c.balanceOf(address(this)) == mySharesBefore && c.totalSupply() == totalSupplyBefore);
    }

    receive() external payable {}
}

